struct F11HoldGuard<'a> {
    child: &'a NativeChild,
    anchor: &'a FocusAnchor,
    armed: bool,
}

impl<'a> F11HoldGuard<'a> {
    fn new(child: &'a NativeChild, anchor: &'a FocusAnchor) -> Self {
        Self {
            child,
            anchor,
            armed: true,
        }
    }

    fn release(&mut self) -> Result<NativeInputEdgeEvidence, String> {
        if !self.armed {
            return Err("F11 hold was already released".into());
        }

        let (foreground, process_id) = capture_foreground();
        let target =
            if process_id == self.child.process_id() || process_id == self.anchor.process_id() {
                foreground
            } else {
                self.anchor.focus()?;
                self.anchor.hwnd()
            };
        let evidence = self.child.release_f11(target)?;
        self.armed = false;
        Ok(evidence)
    }
}

impl Drop for F11HoldGuard<'_> {
    fn drop(&mut self) {
        if self.armed {
            let _ = self.release();
        }
    }
}

pub fn run_suite(
    executable: &str,
    profile: &Path,
    output: &Path,
    trace_path: &Path,
    hold_threshold_ms: u64,
    h6_repeat_mode: H6RepeatMode,
    cursor_restore: Option<POINT>,
    _desktop: &InputDesktopAttachment,
    report: &mut AcceptanceReport,
    runner_log: &mut File,
) -> Option<FocusAnchor> {
    if let Err(error) = preflight_acceptance_hotkey(AcceptanceHotkey::F11) {
        record_environment_failure(
            format!("acceptance hotkey preflight failed: {error}"),
            report,
            output,
            trace_path,
            runner_log,
        );
        return None;
    }
    let _ = writeln!(
        runner_log,
        "acceptance hotkey F11 registered and unregistered successfully before child launch"
    );

    let stdout_path = profile.join("child.stdout.log");
    let stderr_path = profile.join("child.stderr.log");
    let mut child = match NativeChild::launch(
        Path::new(executable),
        profile,
        trace_path,
        &stdout_path,
        &stderr_path,
    ) {
        Ok(child) => child,
        Err(error) => {
            report.environment.child_process_id = error.process_id;
            report.environment.child_started_unix_ms = error.started.and_then(|started| {
                started
                    .duration_since(UNIX_EPOCH)
                    .ok()
                    .map(|duration| duration.as_millis())
            });
            if let Some(inventory) = save_launch_failure_inventory(&error, output) {
                report.push_artifact(inventory.to_string_lossy());
            }
            let failure = CaseFailure::new(FailureStage::CandidateStartup, error.to_string());
            for (index, id) in CASE_IDS
                .into_iter()
                .filter(|id| !DEFERRED_REPORT_CASE_IDS.contains(id))
                .enumerate()
            {
                if index == 0 {
                    append_case(
                        report,
                        id,
                        expected(id),
                        started_now(),
                        Err(failure.clone()),
                        None,
                        output,
                        trace_path,
                    );
                } else {
                    append_case_without_artifacts(
                        report,
                        id,
                        Err(CaseFailure::new(
                            failure.stage,
                            "not run because candidate startup failed; see the first case result"
                                .into(),
                        )),
                    );
                }
            }
            let _ = writeln!(
                runner_log,
                "candidate startup failed pid={:?} windows={} : {failure}",
                error.process_id,
                error.windows.len()
            );
            return None;
        }
    };

    report.environment.child_process_id = Some(child.process_id());
    report.environment.child_started_unix_ms = child
        .started()
        .duration_since(UNIX_EPOCH)
        .ok()
        .map(|duration| duration.as_millis());
    let _ = writeln!(
        runner_log,
        "launched source-matched candidate pid={} root_hwnd={} desktop={} started={:?}",
        child.process_id(),
        hwnd_id(child.root().hwnd),
        child.desktop_name(),
        child.started()
    );

    let anchor = match FocusAnchor::create() {
        Ok(anchor) => anchor,
        Err(error) => {
            let failure = CaseFailure::new(FailureStage::Environment, error);
            for (index, id) in CASE_IDS
                .into_iter()
                .filter(|id| !DEFERRED_REPORT_CASE_IDS.contains(id))
                .enumerate()
            {
                if index == 0 {
                    append_case(
                        report,
                        id,
                        expected(id),
                        started_now(),
                        Err(failure.clone()),
                        Some(&child),
                        output,
                        trace_path,
                    );
                } else {
                    append_case_without_artifacts(
                        report,
                        id,
                        Err(CaseFailure::new(
                            failure.stage,
                            "not run because runner setup failed; see the first case result".into(),
                        )),
                    );
                }
            }
            restore_cursor_before_shutdown(cursor_restore, runner_log);
            stop_child(&mut child, report, runner_log, output, trace_path);
            return None;
        }
    };
    let mut uia: Option<UiAutomation> = None;
    let mut designer_window: Option<WindowSnapshot> = None;
    let mut hold_windows: Option<Vec<WindowSnapshot>> = None;

    run_tap_case(
        report,
        "H0",
        &mut child,
        &anchor,
        trace_path,
        output,
        "focused ROOT tap parks ROOT offscreen with one short-tap path",
        true,
        false,
        1,
    );
    run_tap_case(
        report,
        "H1",
        &mut child,
        &anchor,
        trace_path,
        output,
        "runner-owned focus tap shows and focuses ROOT",
        false,
        true,
        1,
    );
    run_other_focus_case(report, &mut child, &anchor, trace_path, output);
    let (hold_open, hold_guard, hold_observer, hold_observer_error) = run_hold_open_case(
        &child,
        &anchor,
        trace_path,
        hold_threshold_ms,
        &mut hold_windows,
    );
    append_case(
        report,
        "H4",
        expected("H4"),
        started_now(),
        hold_open,
        Some(&child),
        output,
        trace_path,
    );
    let h5_handoff = run_hold_release_case(
        report,
        &child,
        &anchor,
        trace_path,
        output,
        hold_windows.as_deref(),
        hold_guard,
        hold_observer,
        hold_observer_error,
        h6_repeat_mode,
    );
    run_second_hold_case(
        report,
        &child,
        &anchor,
        trace_path,
        output,
        hold_threshold_ms,
        hold_windows.as_deref(),
        h6_repeat_mode,
        h5_handoff,
    );
    run_hotkey_burst_case(
        report,
        "H7",
        &child,
        &anchor,
        trace_path,
        output,
        AcceptanceHotkey::F11,
        3,
    );
    run_hotkey_burst_case(
        report,
        "H8",
        &child,
        &anchor,
        trace_path,
        output,
        AcceptanceHotkey::F11,
        4,
    );

    let ui_result = UiAutomation::new();
    match ui_result {
        Ok(automation) => uia = Some(automation),
        Err(error) => {
            let started = Instant::now();
            append_case(
                report,
                "D0",
                expected("D0"),
                started,
                Err(CaseFailure::new(FailureStage::Environment, error.clone())),
                Some(&child),
                output,
                trace_path,
            );
        }
    }

    if let Some(automation) = uia.as_ref() {
        match run_designer_entry(&mut child, automation, &anchor, trace_path) {
            Ok(entry) => {
                designer_window = Some(entry.window);
                append_case(
                    report,
                    "D0",
                    expected("D0"),
                    started_now(),
                    Ok("one child-owned Designer HWND appeared; UIA root belongs to the child and its InitialSnapshot reply was accepted".into()),
                    None,
                    output,
                    trace_path,
                );
            }
            Err(failure) => {
                append_case(
                    report,
                    "D0",
                    expected("D0"),
                    started_now(),
                    Err(failure.clone()),
                    Some(&child),
                    output,
                    trace_path,
                );
                append_blocked_designer_cases(report, &failure, Some(&child), output, trace_path);
            }
        }
    } else {
        let failure = CaseFailure::new(
            FailureStage::Environment,
            "UI Automation initialization failed".into(),
        );
        append_blocked_designer_cases(report, &failure, Some(&child), output, trace_path);
    }

    run_failure_artifact_case(report, &child, output, trace_path);

    if let (Some(automation), Some(designer)) = (uia.as_ref(), designer_window.as_ref()) {
        run_designer_focus_case(report, &mut child, automation, designer, trace_path, output);
        run_designer_pointer_case(
            report,
            &mut child,
            automation,
            designer,
            trace_path,
            output,
            expected("D1"),
            false,
        );
        run_tab_case(
            report,
            &mut child,
            automation,
            designer,
            output,
            trace_path,
            DESIGNER_STARTER_NAME,
            false,
        );
        run_skins_command_case(report, &mut child, automation, designer, trace_path, output);
        run_designer_close_case(report, &mut child, designer, output, trace_path);
        match run_designer_entry(&mut child, automation, &anchor, trace_path) {
            Ok(entry) => run_authoring_geometry_cases(
                report,
                &mut child,
                automation,
                &anchor,
                profile,
                &entry.window,
                entry.session_id,
                output,
                trace_path,
                None,
            ),
            Err(failure) => {
                append_blocked_authoring_cases(report, &failure, Some(&child), output, trace_path)
            }
        }
    }

    restore_cursor_before_shutdown(cursor_restore, runner_log);
    stop_child(&mut child, report, runner_log, output, trace_path);
    let existing_case_ids = report
        .cases
        .iter()
        .map(|case| case.id.as_str())
        .collect::<Vec<_>>();
    for id in missing_case_ids(&existing_case_ids)
        .into_iter()
        .filter(|id| !DEFERRED_REPORT_CASE_IDS.contains(id))
    {
        append_case_without_artifacts(
            report,
            id,
            Err(CaseFailure::new(
                FailureStage::Cleanup,
                "runner omitted a required case result".into(),
            )),
        );
    }
    let _ = writeln!(
        runner_log,
        "native suite completed with {} case records",
        report.cases.len()
    );
    Some(anchor)
}

pub fn run_hotkey_suite(
    executable: &str,
    profile: &Path,
    output: &Path,
    trace_path: &Path,
    hotkey: AcceptanceHotkey,
    cursor_restore: Option<POINT>,
    _desktop: &InputDesktopAttachment,
    report: &mut AcceptanceReport,
    runner_log: &mut File,
) -> Option<FocusAnchor> {
    if let Err(error) = preflight_acceptance_hotkey(hotkey) {
        record_environment_failure(
            format!("acceptance hotkey preflight failed: {error}"),
            report,
            output,
            trace_path,
            runner_log,
        );
        return None;
    }
    let _ = writeln!(
        runner_log,
        "acceptance hotkey {} registered and unregistered successfully before child launch",
        hotkey.as_str()
    );

    let stdout_path = profile.join("child.stdout.log");
    let stderr_path = profile.join("child.stderr.log");
    let mut child = match NativeChild::launch(
        Path::new(executable),
        profile,
        trace_path,
        &stdout_path,
        &stderr_path,
    ) {
        Ok(child) => child,
        Err(error) => {
            report.environment.child_process_id = error.process_id;
            report.environment.child_started_unix_ms = error.started.and_then(|started| {
                started
                    .duration_since(UNIX_EPOCH)
                    .ok()
                    .map(|duration| duration.as_millis())
            });
            if let Some(inventory) = save_launch_failure_inventory(&error, output) {
                report.push_artifact(inventory.to_string_lossy());
            }
            record_environment_failure(
                format!("candidate startup failed: {error}"),
                report,
                output,
                trace_path,
                runner_log,
            );
            return None;
        }
    };

    report.environment.child_process_id = Some(child.process_id());
    report.environment.child_started_unix_ms = child
        .started()
        .duration_since(UNIX_EPOCH)
        .ok()
        .map(|duration| duration.as_millis());
    let _ = writeln!(
        runner_log,
        "launched source-matched candidate pid={} root_hwnd={} desktop={} hotkey={}",
        child.process_id(),
        hwnd_id(child.root().hwnd),
        child.desktop_name(),
        hotkey.as_str()
    );

    if let Err(error) =
        wait_hotkey_fixture_ready(&child, trace_path, HOTKEY_FIXTURE_STARTUP_TIMEOUT)
    {
        append_hotkey_setup_failures(report, error, Some(&child), output, trace_path, hotkey);
        restore_cursor_before_shutdown(cursor_restore, runner_log);
        stop_child(&mut child, report, runner_log, output, trace_path);
        return None;
    }

    let anchor = match FocusAnchor::create() {
        Ok(anchor) => anchor,
        Err(error) => {
            append_hotkey_setup_failures(report, error, Some(&child), output, trace_path, hotkey);
            restore_cursor_before_shutdown(cursor_restore, runner_log);
            stop_child(&mut child, report, runner_log, output, trace_path);
            return None;
        }
    };

    let hold_threshold_ms = report.profile.hold_threshold_ms;
    run_hotkey_matrix_case(
        report,
        &child,
        &anchor,
        trace_path,
        output,
        hotkey,
        hold_threshold_ms,
    );
    run_hotkey_behavior_cases(
        executable,
        profile,
        report,
        &mut child,
        &anchor,
        trace_path,
        output,
        hotkey,
        hold_threshold_ms,
    );

    restore_cursor_before_shutdown(cursor_restore, runner_log);
    stop_child(&mut child, report, runner_log, output, trace_path);
    for id in HOTKEY_CASE_IDS.into_iter().filter(|id| *id != "R0") {
        if !report.cases.iter().any(|case| case.id == id) {
            append_case_without_artifacts(
                report,
                id,
                Err(CaseFailure::new(
                    FailureStage::Cleanup,
                    "runner omitted a required hotkey case result".into(),
                )),
            );
        }
    }
    let _ = writeln!(
        runner_log,
        "hotkey suite completed with {} case records",
        report.cases.len()
    );
    Some(anchor)
}

pub fn run_query_suite(
    executable: &str,
    profile: &Path,
    output: &Path,
    trace_path: &Path,
    hotkey: AcceptanceHotkey,
    cursor_restore: Option<POINT>,
    _desktop: &InputDesktopAttachment,
    report: &mut AcceptanceReport,
    runner_log: &mut File,
) -> Option<FocusAnchor> {
    if let Err(error) = preflight_acceptance_hotkey(hotkey) {
        record_environment_failure(
            format!("acceptance hotkey preflight failed: {error}"),
            report,
            output,
            trace_path,
            runner_log,
        );
        return None;
    }
    let stdout_path = profile.join("child.stdout.log");
    let stderr_path = profile.join("child.stderr.log");
    let marker_path = profile.join("query-marker-ledger.txt");
    let mut child = match NativeChild::launch(
        Path::new(executable),
        profile,
        trace_path,
        &stdout_path,
        &stderr_path,
    ) {
        Ok(child) => child,
        Err(error) => {
            report.environment.child_process_id = error.process_id;
            report.environment.child_started_unix_ms = error.started.and_then(|started| {
                started
                    .duration_since(UNIX_EPOCH)
                    .ok()
                    .map(|duration| duration.as_millis())
            });
            if let Some(inventory) = save_launch_failure_inventory(&error, output) {
                report.push_artifact(inventory.to_string_lossy());
            }
            record_environment_failure(
                format!("Query candidate startup failed: {error}"),
                report,
                output,
                trace_path,
                runner_log,
            );
            return None;
        }
    };
    report.environment.child_process_id = Some(child.process_id());
    report.environment.child_started_unix_ms = child
        .started()
        .duration_since(UNIX_EPOCH)
        .ok()
        .map(|duration| duration.as_millis());
    let anchor = match wait_hotkey_fixture_ready(&child, trace_path, HOTKEY_FIXTURE_STARTUP_TIMEOUT)
        .and_then(|_| FocusAnchor::create())
    {
        Ok(anchor) => anchor,
        Err(error) => {
            record_environment_failure(
                format!("Query runner setup failed: {error}"),
                report,
                output,
                trace_path,
                runner_log,
            );
            restore_cursor_before_shutdown(cursor_restore, runner_log);
            stop_child(&mut child, report, runner_log, output, trace_path);
            return None;
        }
    };
    let ui = match UiAutomation::new() {
        Ok(ui) => ui,
        Err(error) => {
            record_environment_failure(
                format!("Query UI Automation setup failed: {error}"),
                report,
                output,
                trace_path,
                runner_log,
            );
            restore_cursor_before_shutdown(cursor_restore, runner_log);
            stop_child(&mut child, report, runner_log, output, trace_path);
            return Some(anchor);
        }
    };
    let hold_threshold_ms = report.profile.hold_threshold_ms;
    run_query_case(
        report,
        "Q02",
        &child,
        &anchor,
        &ui,
        trace_path,
        output,
        marker_path.as_path(),
        hotkey,
        hold_threshold_ms,
        || {
            run_query_invocation(
                &child,
                &anchor,
                &ui,
                trace_path,
                output,
                marker_path.as_path(),
                hotkey,
                hold_threshold_ms,
                "qa-open",
                false,
                None,
                |child, ui, _events| {
                    wait_launcher_query(child, ui, "app QMarker")?;
                    Ok(QueryEffectResult {
                        effect_count: 0,
                        cancelled_confirmation_count: 0,
                        ui_ack: QueryEvidenceUiAck::LauncherQuery,
                    })
                },
            )
        },
    );
    run_query_case(
        report,
        "Q03",
        &child,
        &anchor,
        &ui,
        trace_path,
        output,
        marker_path.as_path(),
        hotkey,
        hold_threshold_ms,
        || {
            let before = marker_occurrences(marker_path.as_path(), "q-first")?;
            run_query_invocation(
                &child,
                &anchor,
                &ui,
                trace_path,
                output,
                marker_path.as_path(),
                hotkey,
                hold_threshold_ms,
                "qa-hidden-first",
                false,
                Some(false),
                |_child, _ui, _events| {
                    wait_marker_occurrences(marker_path.as_path(), "q-first", before + 1)?;
                    Ok(QueryEffectResult {
                        effect_count: 1,
                        cancelled_confirmation_count: 0,
                        ui_ack: QueryEvidenceUiAck::None,
                    })
                },
            )
        },
    );
    run_query_case(
        report,
        "Q05",
        &child,
        &anchor,
        &ui,
        trace_path,
        output,
        marker_path.as_path(),
        hotkey,
        hold_threshold_ms,
        || {
            let before = marker_occurrences(marker_path.as_path(), "q-second")?;
            run_query_invocation(
                &child,
                &anchor,
                &ui,
                trace_path,
                output,
                marker_path.as_path(),
                hotkey,
                hold_threshold_ms,
                "qa-pinned-second",
                false,
                Some(false),
                |_child, _ui, _events| {
                    wait_marker_occurrences(marker_path.as_path(), "q-second", before + 1)?;
                    Ok(QueryEffectResult {
                        effect_count: 1,
                        cancelled_confirmation_count: 0,
                        ui_ack: QueryEvidenceUiAck::None,
                    })
                },
            )
        },
    );
    run_query_case(
        report,
        "Q07",
        &child,
        &anchor,
        &ui,
        trace_path,
        output,
        marker_path.as_path(),
        hotkey,
        hold_threshold_ms,
        || {
            run_query_invocation(
                &child,
                &anchor,
                &ui,
                trace_path,
                output,
                marker_path.as_path(),
                hotkey,
                hold_threshold_ms,
                "qa-no-results",
                false,
                None,
                |child, ui, _events| {
                    wait_launcher_query(child, ui, "qa-no-such-result-9f42d2")?;
                    let root = child.refresh_root().map_err(query_window_error)?;
                    ui.wait_visible_text(
                        root.hwnd,
                        child.process_id(),
                        "No launcher result is currently available for \"qa-no-such-result-9f42d2\"; opening the saved query",
                        UIA_TIMEOUT,
                    )
                    .map_err(|error| {
                        CaseFailure::new(
                            FailureStage::NativeRootState,
                            format!("no-result explanation was not exposed: {error}"),
                        )
                    })?;
                    Ok(QueryEffectResult {
                        effect_count: 0,
                        cancelled_confirmation_count: 0,
                        ui_ack: QueryEvidenceUiAck::LauncherQuery,
                    })
                },
            )
        },
    );
    run_query_case(
        report,
        "Q10",
        &child,
        &anchor,
        &ui,
        trace_path,
        output,
        marker_path.as_path(),
        hotkey,
        hold_threshold_ms,
        || {
            let mut invocations = Vec::new();
            let before_hidden = marker_occurrences(marker_path.as_path(), "q-first")?;
            invocations.push(run_query_invocation(
                &child,
                &anchor,
                &ui,
                trace_path,
                output,
                marker_path.as_path(),
                hotkey,
                hold_threshold_ms,
                "qa-visible-first",
                false,
                Some(false),
                |_child, _ui, _events| {
                    wait_marker_occurrences(marker_path.as_path(), "q-first", before_hidden + 1)?;
                    Ok(QueryEffectResult {
                        effect_count: 1,
                        cancelled_confirmation_count: 0,
                        ui_ack: QueryEvidenceUiAck::None,
                    })
                },
            )?);
            let before_visible = marker_occurrences(marker_path.as_path(), "q-first")?;
            invocations.push(run_query_invocation(
                &child,
                &anchor,
                &ui,
                trace_path,
                output,
                marker_path.as_path(),
                hotkey,
                hold_threshold_ms,
                "qa-visible-first",
                true,
                Some(true),
                |_child, _ui, _events| {
                    wait_marker_occurrences(marker_path.as_path(), "q-first", before_visible + 1)?;
                    Ok(QueryEffectResult {
                        effect_count: 1,
                        cancelled_confirmation_count: 0,
                        ui_ack: QueryEvidenceUiAck::None,
                    })
                },
            )?);
            Ok(invocations)
        },
    );
    run_query_case(
        report,
        "Q11",
        &child,
        &anchor,
        &ui,
        trace_path,
        output,
        marker_path.as_path(),
        hotkey,
        hold_threshold_ms,
        || {
            run_query_invocation(
                &child,
                &anchor,
                &ui,
                trace_path,
                output,
                marker_path.as_path(),
                hotkey,
                hold_threshold_ms,
                "qa-note-new",
                false,
                None,
                |child, ui, _events| {
                    wait_note_editor(child, ui, "# radial acceptance q11", output)?;
                    Ok(QueryEffectResult {
                        effect_count: 1,
                        cancelled_confirmation_count: 0,
                        ui_ack: QueryEvidenceUiAck::NoteEditor,
                    })
                },
            )
        },
    );
    run_query_case(
        report,
        "Q12",
        &child,
        &anchor,
        &ui,
        trace_path,
        output,
        marker_path.as_path(),
        hotkey,
        hold_threshold_ms,
        || {
            run_query_invocation(
                &child,
                &anchor,
                &ui,
                trace_path,
                output,
                marker_path.as_path(),
                hotkey,
                hold_threshold_ms,
                "qa-launcher-show",
                false,
                None,
                |child, ui, _events| {
                    wait_launcher_query(child, ui, "qa-explicit-launcher")?;
                    Ok(QueryEffectResult {
                        effect_count: 1,
                        cancelled_confirmation_count: 0,
                        ui_ack: QueryEvidenceUiAck::LauncherQuery,
                    })
                },
            )
        },
    );
    run_query_case(
        report,
        "Q13",
        &child,
        &anchor,
        &ui,
        trace_path,
        output,
        marker_path.as_path(),
        hotkey,
        hold_threshold_ms,
        || {
            let note_path = profile.join("notes").join("radial-acceptance-q13.md");
            if !note_path.is_file() {
                return Err(CaseFailure::new(
                    FailureStage::Cleanup,
                    "isolated destructive-action note was missing before confirmation test".into(),
                ));
            }
            let mut invocations = Vec::new();
            invocations.push(run_query_invocation(
                &child,
                &anchor,
                &ui,
                trace_path,
                output,
                marker_path.as_path(),
                hotkey,
                hold_threshold_ms,
                "qa-note-remove",
                true,
                Some(true),
                |child, ui, _events| {
                    click_confirmation_control(child, ui, "Cancel", trace_path)?;
                    if !note_path.is_file() {
                        return Err(CaseFailure::new(
                            FailureStage::GestureDecision,
                            "cancelled note removal changed the isolated file".into(),
                        ));
                    }
                    Ok(QueryEffectResult {
                        effect_count: 0,
                        cancelled_confirmation_count: 1,
                        ui_ack: QueryEvidenceUiAck::Cancelled,
                    })
                },
            )?);
            invocations.push(run_query_invocation(
                &child,
                &anchor,
                &ui,
                trace_path,
                output,
                marker_path.as_path(),
                hotkey,
                hold_threshold_ms,
                "qa-note-remove",
                true,
                Some(true),
                |child, ui, _events| {
                    click_confirmation_control(child, ui, "Confirm", trace_path)?;
                    wait_until(UIA_TIMEOUT, || !note_path.exists());
                    if note_path.exists() {
                        return Err(CaseFailure::new(
                            FailureStage::NativeRootState,
                            "confirmed note removal did not remove the isolated file".into(),
                        ));
                    }
                    Ok(QueryEffectResult {
                        effect_count: 1,
                        cancelled_confirmation_count: 0,
                        ui_ack: QueryEvidenceUiAck::Confirmed,
                    })
                },
            )?);
            Ok(invocations)
        },
    );
    run_query_case(
        report,
        "Q15",
        &child,
        &anchor,
        &ui,
        trace_path,
        output,
        marker_path.as_path(),
        hotkey,
        hold_threshold_ms,
        || {
            let before = marker_occurrences(marker_path.as_path(), "q-exact")?;
            run_query_invocation(
                &child,
                &anchor,
                &ui,
                trace_path,
                output,
                marker_path.as_path(),
                hotkey,
                hold_threshold_ms,
                "qa-exact-marker",
                false,
                Some(false),
                |_child, _ui, _events| {
                    wait_marker_occurrences(marker_path.as_path(), "q-exact", before + 1)?;
                    Ok(QueryEffectResult {
                        effect_count: 1,
                        cancelled_confirmation_count: 0,
                        ui_ack: QueryEvidenceUiAck::None,
                    })
                },
            )
        },
    );

    restore_cursor_before_shutdown(cursor_restore, runner_log);
    stop_child(&mut child, report, runner_log, output, trace_path);
    for id in QUERY_CASE_IDS
        .into_iter()
        .filter(|id| !matches!(*id, "CLEANUP" | "R0"))
    {
        if !report.cases.iter().any(|case| case.id == id) {
            append_case_without_artifacts(
                report,
                id,
                Err(CaseFailure::new(
                    FailureStage::Cleanup,
                    "runner omitted a required Query case result".into(),
                )),
            );
        }
    }
    Some(anchor)
}

